class IsJournalAuthor(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        return obj.patient == request.user

class MentalHealthJournalViewSet(viewsets.ModelViewSet):
    serializer_class = JournalEntrySerializer
    permission_classes = [permissions.IsAuthenticated, IsJournalAuthor]

    def get_queryset(self):
        return MentalHealthJournal.objects.filter(patient=self.request.user)
